import React, { useState, useEffect, useCallback, useRef } from 'react';
import './DragDropDashboard.css';

interface DashboardItem {
  id: string;
  component: React.ReactNode;
  title: string;
  defaultPosition: { x: number; y: number; width: number; height: number };
  minWidth?: number;
  minHeight?: number;
  resizable?: boolean;
}

interface Position {
  x: number;
  y: number;
  width: number;
  height: number;
  zIndex: number;
}

interface DragDropDashboardProps {
  items: DashboardItem[];
  storageKey?: string;
  className?: string;
}

interface DraggableItemProps {
  item: DashboardItem;
  position: Position;
  onPositionChange: (id: string, position: Partial<Position>) => void;
  onBringToFront: (id: string) => void;
}

const DraggableItem: React.FC<DraggableItemProps> = ({
  item,
  position,
  onPositionChange,
  onBringToFront
}) => {
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const dragRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    const target = e.target as HTMLElement;
    const isHeader = target.classList.contains('dashboard-item-header') || 
                    target.classList.contains('dashboard-item-title') ||
                    target.closest('.dashboard-item-header');
    
    if (isHeader && !target.classList.contains('minimize-btn') && !target.classList.contains('maximize-btn')) {
      setIsDragging(true);
      setDragStart({ 
        x: e.clientX - position.x, 
        y: e.clientY - position.y 
      });
      onBringToFront(item.id);
      e.preventDefault();
      e.stopPropagation();
    }
  }, [position.x, position.y, onBringToFront, item.id]);

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (isDragging) {
      const containerRect = dragRef.current?.parentElement?.getBoundingClientRect();
      const maxX = containerRect ? containerRect.width - position.width : window.innerWidth - position.width;
      const maxY = containerRect ? containerRect.height - position.height : window.innerHeight - position.height;
      
      const newX = Math.max(0, Math.min(maxX, e.clientX - dragStart.x));
      const newY = Math.max(0, Math.min(maxY, e.clientY - dragStart.y));
      
      onPositionChange(item.id, { x: newX, y: newY });
    } else if (isResizing) {
      const newWidth = Math.max(item.minWidth || 300, e.clientX - position.x);
      const newHeight = Math.max(item.minHeight || 200, e.clientY - position.y);
      onPositionChange(item.id, { width: newWidth, height: newHeight });
    }
  }, [isDragging, isResizing, dragStart, position, onPositionChange, item.id, item.minWidth, item.minHeight]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    setIsResizing(false);
  }, []);

  const handleResizeStart = useCallback((e: React.MouseEvent) => {
    setIsResizing(true);
    e.preventDefault();
    e.stopPropagation();
  }, []);

  useEffect(() => {
    if (isDragging || isResizing) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.userSelect = 'none';
      
      return () => {
        document.removeEventListener('mousemove', handleMouseMove);
        document.removeEventListener('mouseup', handleMouseUp);
        document.body.style.userSelect = '';
      };
    }
  }, [isDragging, isResizing, handleMouseMove, handleMouseUp]);

  return (
    <div
      ref={dragRef}
      className={`dashboard-item ${isDragging ? 'dragging' : ''} ${isResizing ? 'resizing' : ''}`}
      style={{
        position: 'absolute',
        left: position.x,
        top: position.y,
        width: position.width,
        height: position.height,
        zIndex: position.zIndex,
      }}
      onClick={() => onBringToFront(item.id)}
    >
      <div 
        className="dashboard-item-header"
        onMouseDown={handleMouseDown}
        style={{ cursor: isDragging ? 'grabbing' : 'grab' }}
      >
        <span className="dashboard-item-title">{item.title}</span>
        <div className="dashboard-item-controls">
          <button 
            className="minimize-btn"
            onClick={(e) => {
              e.stopPropagation();
              // Add minimize functionality
            }}
          >
            −
          </button>
          <button 
            className="maximize-btn"
            onClick={(e) => {
              e.stopPropagation();
              // Add maximize functionality
            }}
          >
            □
          </button>
        </div>
      </div>
      <div className="dashboard-item-content">
        {item.component}
      </div>
      {item.resizable !== false && (
        <div 
          className="resize-handle"
          onMouseDown={handleResizeStart}
        />
      )}
    </div>
  );
};

const DragDropDashboard: React.FC<DragDropDashboardProps> = ({
  items,
  storageKey = 'dashboard-layout',
  className = ''
}) => {
  const [positions, setPositions] = useState<Record<string, Position>>({});
  const [maxZIndex, setMaxZIndex] = useState(1000);

  // Load positions from localStorage
  useEffect(() => {
    const savedPositions = localStorage.getItem(storageKey);
    if (savedPositions) {
      try {
        const parsed = JSON.parse(savedPositions);
        setPositions(parsed);
      } catch (error) {
        console.error('Failed to parse saved positions:', error);
      }
    } else {
      // Initialize with default positions
      const defaultPositions: Record<string, Position> = {};
      items.forEach((item, index) => {
        defaultPositions[item.id] = {
          ...item.defaultPosition,
          zIndex: 1000 + index
        };
      });
      setPositions(defaultPositions);
    }
  }, [items, storageKey]);

  // Save positions to localStorage
  useEffect(() => {
    if (Object.keys(positions).length > 0) {
      localStorage.setItem(storageKey, JSON.stringify(positions));
    }
  }, [positions, storageKey]);

  const handlePositionChange = useCallback((id: string, newPosition: Partial<Position>) => {
    setPositions(prev => ({
      ...prev,
      [id]: { ...prev[id], ...newPosition }
    }));
  }, []);

  const handleBringToFront = useCallback((id: string) => {
    const newZIndex = maxZIndex + 1;
    setMaxZIndex(newZIndex);
    handlePositionChange(id, { zIndex: newZIndex });
  }, [maxZIndex, handlePositionChange]);

  const resetLayout = () => {
    const defaultPositions: Record<string, Position> = {};
    items.forEach((item, index) => {
      defaultPositions[item.id] = {
        ...item.defaultPosition,
        zIndex: 1000 + index
      };
    });
    setPositions(defaultPositions);
    localStorage.removeItem(storageKey);
  };

  return (
    <div className={`drag-drop-dashboard ${className}`}>
      <div className="dashboard-controls">
        <button onClick={resetLayout} className="reset-layout-btn">
          Reset Layout
        </button>
      </div>
      <div className="dashboard-container">
        {items.map((item) => {
          const position = positions[item.id];
          if (!position) return null;

          return (
            <DraggableItem
              key={item.id}
              item={item}
              position={position}
              onPositionChange={handlePositionChange}
              onBringToFront={handleBringToFront}
            />
          );
        })}
      </div>
    </div>
  );
};

export default DragDropDashboard;
